using System;
[Serializable] public sealed class ForgeOption { public string id, label, defenderKind, faceKind, modeCost; public int attackerId, defenderId, order; public bool requiresPaymentCheck, selected; public ForgeCardView card, castingFace; public ForgeStackItem ability; }
[Serializable] public sealed class ForgeRequest { public long requestId, contextId; public int seat, selectedCount, remainingCount, sourceCardId, minCount, maxCount, selectedValue, requiredValue, minValue, maxValue; public string kind, message, abilityText, abilityKind, selectionPurpose; public ForgeCardView sourceCard; public ForgeOption[] options; public ForgeCardView[] previewCards; public ForgeStackItem[] orderedAbilities; public ForgeAllocation[] allocations; }
[Serializable] public sealed class ForgeAllocation { public int id, amount; public string label; public ForgeCardView card; }
[Serializable] public sealed class ForgeCardCounter { public string kind,label; public int count; }
[Serializable] public sealed class ForgePreparedSpellView {
    public int id,ownerSeat;
    public string name,printingKey,stateName,currentRules,currentType,manaCost,zone;
    public ForgeCardView ToCard()=>new ForgeCardView{id=id,ownerSeat=ownerSeat,name=name,printingKey=printingKey,stateName=stateName,currentRules=currentRules,currentType=currentType,manaCost=manaCost,zone=zone};
}
[Serializable] public sealed class ForgeCardView { public ForgePreparedSpellView preparedSpell; public int devotion, devotionRequired; public bool stackableSupport, emblem, effectMarker; public string markerKind,markerStatus,helperArtName; public string faceDownKind, knownFaceName, knownFaceRules, knownFacePrintingKey; public bool hasStatBaseline; public int basePower, baseToughness; public string[] grantedKeywords; public int id, power, toughness, damage, defenderId, loyalty, defense, ownerSeat; public int[] blockedAttackerIds; public ForgeCardCounter[] counters; public string[] keywords, basicLandTypes; public string tokenSourcePrintingKey, tokenArtKey; public bool token, copy; public string name, printingKey, defenderKind, selection, stateName, originalRules, originalType, currentRules, currentType, manaCost, zone, leftRoom, rightRoom; public bool hasCurrentLandState, landTypesChanged; public bool tapped, faceDown, creature, land, attacking, blocking, planeswalker, battle, backFace, room, leftRoomUnlocked, rightRoomUnlocked; }
[Serializable] public sealed class ForgePlayerView { public int speed,ringTemptedCount,ringBearerId; public ForgeCardCounter[] counters; public string[] completedDungeons; public int seat, targetId, life, handCount, libraryCount, exileCount, redMana; public int[] manaPool; public ForgeCardView[] hand, battlefield, emblems, effectMarkers, graveyardCards, exileCards, reviewLibrary, reviewGraveyard, reviewExile; public string[] graveyard; }
[Serializable] public sealed class ForgeStackItem { public int id, controllerSeat, xValue; public bool hasXValue; public string description, kind; public ForgeCardView source; public bool copied; }
[Serializable] public sealed class ForgeSeatView { public ForgeCardView[] globalEffects; public ForgeCardView[] playableExile, playableGraveyard; public bool awaitingInput, canRespond, inputPending; public int seat, stackCount, turn, turnSeat, prioritySeat; public string phase,dayTime; public string[] stack; public ForgeStackItem[] stackItems; public ForgePlayerView[] players; public ForgeRequest request; }
[Serializable] public sealed class ForgeWireMessage { public string type, session, error; public long requestId; public int winnerSeat; public ForgeRequest request; public ForgeSeatView[] views; }
[Serializable] public sealed class ForgeResponse { public string type = "respond", session, option; public int seat; public long requestId; }
